from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up all devices.
prime_hub = PrimeHub()
left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
right = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(left, right, 66, 150)
MM_Left = Motor(Port.C, Direction.CLOCKWISE)
MM_Right = Motor(Port.D, Direction.CLOCKWISE)

# Initialize variables.
myWhite = 100
myBlack = 0
targetValue = 50
baseSpeed_2 = 200
turnAmount = 10
mission = 0
max_mission = 3
running = 0
targetAngle_2 = 0
currentAngle_2 = 0
error_2 = 0
correction_2 = 0
Kp_2 = 2
distance = 0

def my_task():
    pass

def DriveStraight_2(dist):
    global targetAngle_2, baseSpeed_2, currentAngle_2, error_2, correction_2
    drive_base.use_gyro(True)
    drive_base.reset(0, 0)
    targetAngle_2 = 0
    baseSpeed_2 = 500
    while not drive_base.distance() >= dist:
        currentAngle_2 = drive_base.angle()
        error_2 = targetAngle_2 - currentAngle_2
        correction_2 = Kp_2 * error_2
        drive_base.drive(baseSpeed_2, correction_2)
    drive_base.straight(0)


# The main program starts here.
drive_base.settings(straight_acceleration=300)
drive_base.settings(straight_speed=500)
wait(0)
drive_base.straight(760)
print(drive_base.angle())
wait(0)
# motor dip 1st
drive_base.turn(25)
wait(0)
MM_Left.run_angle(255, 60)
wait(0)
drive_base.straight(20)
wait(0)
MM_Left.run_angle(255, 60)
# Go Back!
wait(0)
drive_base.straight(-50)
wait(0)
drive_base.turn(-30)
wait(0)
drive_base.straight(-750)
